describe('User Mention in Comments', () => {
  const baseUrl = Cypress.env('BASE_URL') || 'http://localhost:3000';
  const testUser = {
    email: 'testuser@example.com',
    password: 'TestPassword123!',
    username: 'testuser'
  };
  const mentionedUser = {
    email: 'mentioneduser@example.com',
    username: 'mentioneduser'
  };

  beforeEach(() => {
    cy.visit(`${baseUrl}`);
    cy.clearCookies();
    cy.clearLocalStorage();

    // Login as test user
    cy.get('[data-testid="login-email"]').type(testUser.email);
    cy.get('[data-testid="login-password"]').type(testUser.password);
    cy.get('[data-testid="login-submit"]').click();
    cy.url().should('include', '/dashboard');
    cy.wait(1000);
  });

  it('should successfully mention a user in a comment using @ symbol', () => {
    // Navigate to a post or comment section
    cy.get('[data-testid="post-item"]').first().click();
    cy.wait(500);

    // Click on comment input field
    cy.get('[data-testid="comment-input"]').click();
    cy.get('[data-testid="comment-input"]').type('@');

    // Verify mention dropdown appears
    cy.get('[data-testid="mention-dropdown"]').should('be.visible');
    cy.get('[data-testid="mention-dropdown"]').should('contain', mentionedUser.username);

    // Select mentioned user from dropdown
    cy.get(`[data-testid="mention-option-${mentionedUser.username}"]`).click();

    // Verify mention is inserted correctly
    cy.get('[data-testid="comment-input"]').should('contain.value', `@${mentionedUser.username}`);

    // Complete the comment
    cy.get('[data-testid="comment-input"]').type(' this is a test mention');
    cy.get('[data-testid="comment-submit"]').click();

    // Verify comment was posted with mention
    cy.get('[data-testid="comment-list"]').should('contain', `@${mentionedUser.username}`);
    cy.get('[data-testid="comment-list"]').should('contain', 'this is a test mention');

    // Verify mention is highlighted/linked
    cy.get('[data-testid="comment-mention"]').should('have.class', 'mention-link');
  });

  it('should filter mention suggestions as user types after @ symbol', () => {
    cy.get('[data-testid="post-item"]').first().click();
    cy.wait(500);

    cy.get('[data-testid="comment-input"]').click();
    cy.get('[data-testid="comment-input"]').type('@men');

    // Verify dropdown filters results
    cy.get('[data-testid="mention-dropdown"]').should('be.visible');
    cy.get('[data-testid="mention-dropdown"]').should('contain', mentionedUser.username);

    // Verify non-matching users are not shown
    cy.get('[data-testid="mention-dropdown"]').should('not.contain', 'randomuser');

    // Continue typing to narrow results
    cy.get('[data-testid="comment-input"]').type('tioned');
    cy.get(`[data-testid="mention-option-${mentionedUser.username}"]`).should('be.visible');
  });

  it('should handle multiple mentions in a single comment', () => {
    const secondMentionedUser = 'anotheruser';

    cy.get('[data-testid="post-item"]').first().click();
    cy.wait(500);

    cy.get('[data-testid="comment-input"]').click();
    cy.get('[data-testid="comment-input"]').type(`@${mentionedUser.username} `);
    cy.get(`[data-testid="mention-option-${mentionedUser.username}"]`).click();

    // Add second mention
    cy.get('[data-testid="comment-input"]').type(`and @${secondMentionedUser} `);
    cy.get(`[data-testid="mention-option-${secondMentionedUser}"]`).click();

    cy.get('[data-testid="comment-input"]').type('check this out');
    cy.get('[data-testid="comment-submit"]').click();

    // Verify both mentions are in the comment
    cy.get('[data-testid="comment-list"]').should('contain', `@${mentionedUser.username}`);
    cy.get('[data-testid="comment-list"]').should('contain', `@${secondMentionedUser}`);
  });

  it('should not show mention dropdown when @ is not at word boundary', () => {
    cy.get('[data-testid="post-item"]').first().click();
    cy.wait(500);

    cy.get('[data-testid="comment-input"]').click();
    cy.get('[data-testid="comment-input"]').type('email@example.com');

    // Mention dropdown should not appear for email addresses
    cy.get('[data-testid="mention-dropdown"]').should('not.exist');
  });

  it('should escape mention when @ symbol is preceded by alphanumeric character', () => {
    cy.get('[data-testid="post-item"]').first().click();
    cy.wait(500);

    cy.get('[data-testid="comment-input"]').click();
    cy.get('[data-testid="comment-input"]').type('test@mention');

    // Dropdown should not appear
    cy.get('[data-testid="mention-dropdown"]').should('not.exist');

    // Type with space before @
    cy.get('[data-testid="comment-input"]').clear();
    cy.get('[data-testid="comment-input"]').type('test @');

    // Now dropdown should appear
    cy.get('[data-testid="mention-dropdown"]').should('be.visible');
  });

  it('should notify mentioned user about the mention', () => {
    cy.get('[data-testid="post-item"]').first().click();
    cy.wait(500);

    cy.get('[data-testid="comment-input"]').click();
    cy.get('[data-testid="comment-input"]').type(`@${mentionedUser.username} check this`);
    cy.get(`[data-testid="mention-option-${mentionedUser.username}"]`).click();
    cy.get('[data-testid="comment-submit"]').click();

    // Verify notification was sent (check via API or notification system)
    cy.get('[data-testid="notification-badge"]').should('exist');

    // Logout and login as mentioned user
    cy.get('[data-testid="user-menu"]').click();
    cy.get('[data-testid="logout-button"]').click();

    cy.get('[data-testid="login-email"]').type(mentionedUser.email);
    cy.get('[data-testid="login-password"]').type('MentionedUserPassword123!');
    cy.get('[data-testid="login-submit"]').click();

    // Verify mentioned user sees notification
    cy.get('[data-testid="notification-badge"]').should('contain', '1');
    cy.get('[data-testid="notification-item"]').should('contain', testUser.username);
  });

